(S/'reference/final_reporting_corrections.json').write_text(json.dumps({'corrections':records,'reason':'Strict independent peptide/context gates, not changes to scientific data or thresholds','H00020_mouse_omega_deg':-153.6972230638966,'trans_deviation_deg':26.3027769361034,'predeclared_maximum_deviation_deg':25.,'T3070400_and_T3080401':'one binder heavy atom each below2A in fixed1IVO context'},indent=2))
